function defaults(object,index){return {...object,id:object.id||`obj-${object.number}`,loops:object.loops||[{number:'1',name:'Шлейф 1',description:'Входная дверь',zone:'Охранная'},{number:'2',name:'Шлейф 2',description:'Объёмный датчик',zone:'Охранная'}],contacts:object.contacts||[{name:`${['Иванов Александр Х.','Петров Александр Ю.','Орлов Михаил Л.'][index%3]}`,role:'Администратор',phone:'+7 (983) 825-44-27',priority:'1'},{name:'Смирнова Елена В.',role:'Ответственное лицо',phone:'+7 (906) 826-81-56',priority:'2'}],photos:object.photos||[],mobile:object.mobile||{accountId:'',phone:'',alarm:true,arm:false,power:false,gbr:true}};}
let objects;try{objects=JSON.parse(localStorage.getItem('neva-admin-objects'))||seedObjects.map(defaults);}catch(error){objects=seedObjects.map(defaults);}objects=objects.map(defaults);
let selectedId=objects[0]?.id;
const form=$('objectForm');
function escapeHtml(value=''){return String(value).replace(/[&<>"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]));}
function normalize(value=''){return String(value).toLowerCase().replace(/ё/g,'е').replace(/[^a-zа-я0-9]+/gi,' ').trim();}
function matches(object,query){if(!query)return true;const q=normalize(query);if(normalize(object.number).startsWith(q))return true;return [object.name,object.address].some(value=>normalize(value).split(' ').some(word=>word.startsWith(q))||normalize(value).includes(q));}
function current(){return objects.find(object=>object.id===selectedId);}
function saveStore(){try{localStorage.setItem('neva-admin-objects',JSON.stringify(objects));}catch(error){toast('Недостаточно места: удалите часть фотографий');}}
function toast(message){$('adminToast').textContent=message;$('adminToast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('adminToast').classList.remove('show'),2200);}
function filteredObjects(){const query=$('adminSearch').value,system=$('systemFilter').value,category=$('categoryFilter').value;return objects.filter(object=>matches(object,query)&&(!system||object.system===system)&&(!category||String(object.category)===category)).sort((a,b)=>Number(a.number)-Number(b.number)||a.name.localeCompare(b.name,'ru'));}
function renderList(){const filtered=filteredObjects();$('objectCount').textContent=`Показано ${filtered.length} из ${objects.length}`;$('adminObjectList').innerHTML=filtered.length?filtered.map(object=>{const letter=systemLetter[object.system]||'?';return `<button class="admin-object-card ${object.id===selectedId?'active':''}" data-id="${escapeHtml(object.id)}"><span class="system-letter ${letter.toLowerCase()}">${letter}</span><span><b>${escapeHtml(object.name)}</b><small>${escapeHtml(object.address)}</small></span><em>№ ${escapeHtml(object.number)}</em></button>`;}).join(''):'<div class="photo-empty">Объекты не найдены</div>';document.querySelectorAll('.admin-object-card').forEach(button=>button.addEventListener('click',()=>selectObject(button.dataset.id)));}
function renderSuggestions(){const query=$('adminSearch').value.trim();if(!query){$('adminSuggestions').hidden=true;return;}const suggestions=objects.filter(object=>matches(object,query)).sort((a,b)=>Number(a.number)-Number(b.number)||a.name.localeCompare(b.name,'ru')).slice(0,7);$('adminSuggestions').innerHTML=suggestions.map(object=>`<button data-id="${escapeHtml(object.id)}"><b>${escapeHtml(object.number)}</b> · ${escapeHtml(object.name)}<br><small>${escapeHtml(object.address)}</small></button>`).join('');$('adminSuggestions').hidden=!suggestions.length;document.querySelectorAll('#adminSuggestions button').forEach(button=>button.addEventListener('click',()=>{$('adminSearch').value='';$('adminSuggestions').hidden=true;selectObject(button.dataset.id);}));}
function selectObject(id){selectedId=id;renderList();renderEditor();}
function renderEditor(){const object=current();if(!object)return;const letter=systemLetter[object.system]||'?';$('editorSystemBadge').textContent=letter;$('editorSystemBadge').className=`admin-system-badge ${letter.toLowerCase()}`;$('editorTitle').textContent=object.name;$('editorSubtitle').textContent=`Пультовый № ${object.number} • ${object.system} • ${object.address}`;[...form.elements].forEach(field=>{if(field.name)field.value=object[field.name]??'';});renderLoops();renderContacts();renderPhotos();renderMobile();}
function renderLoops(){const object=current();$('loopsCount').textContent=object.loops.length;$('adminLoopsBody').innerHTML=object.loops.map((loop,index)=>`<tr data-index="${index}"><td><input data-key="number" value="${escapeHtml(loop.number)}"></td><td><input data-key="name" value="${escapeHtml(loop.name)}"></td><td><input data-key="description" value="${escapeHtml(loop.description)}"></td><td><select data-key="zone"><option ${loop.zone==='Охранная'?'selected':''}>Охранная</option><option ${loop.zone==='Пожарная'?'selected':''}>Пожарная</option><option ${loop.zone==='Технологическая'?'selected':''}>Технологическая</option><option ${loop.zone==='КТС'?'selected':''}>КТС</option></select></td><td><button class="remove-row" data-remove-loop="${index}">×</button></td></tr>`).join('');bindTable('adminLoopsBody','loops');document.querySelectorAll('[data-remove-loop]').forEach(button=>button.addEventListener('click',()=>{object.loops.splice(Number(button.dataset.removeLoop),1);renderLoops();}));}
function renderContacts(){const object=current();$('contactsCount').textContent=object.contacts.length;$('adminContactsBody').innerHTML=object.contacts.map((contact,index)=>`<tr data-index="${index}"><td><input data-key="name" value="${escapeHtml(contact.name)}"></td><td><input data-key="role" value="${escapeHtml(contact.role)}"></td><td><input data-key="phone" value="${escapeHtml(contact.phone)}"></td><td><input data-key="priority" type="number" min="1" value="${escapeHtml(contact.priority)}"></td><td><button class="remove-row" data-remove-contact="${index}">×</button></td></tr>`).join('');bindTable('adminContactsBody','contacts');document.querySelectorAll('[data-remove-contact]').forEach(button=>button.addEventListener('click',()=>{object.contacts.splice(Number(button.dataset.removeContact),1);renderContacts();}));}
function bindTable(bodyId,key){document.querySelectorAll(`#${bodyId} input,#${bodyId} select`).forEach(field=>field.addEventListener('input',()=>{current()[key][Number(field.closest('tr').dataset.index)][field.dataset.key]=field.value;}));}
function renderPhotos(){const photos=current().photos;$('adminPhotoGrid').innerHTML=photos.length?photos.map((photo,index)=>`<figure class="admin-photo"><img src="${photo}" alt="Фото объекта ${index+1}"><button data-remove-photo="${index}" aria-label="Удалить фото">×</button></figure>`).join(''):'<div class="photo-empty">Фотографии ещё не добавлены</div>';document.querySelectorAll('[data-remove-photo]').forEach(button=>button.addEventListener('click',()=>{photos.splice(Number(button.dataset.removePhoto),1);renderPhotos();}));}
function renderMobile(){const mobile=current().mobile;$('mobileAccountId').value=mobile.accountId||'';$('mobilePhone').value=mobile.phone||'';document.querySelectorAll('[data-mobile-setting]').forEach(input=>input.checked=Boolean(mobile[input.dataset.mobileSetting]));const connected=Boolean(mobile.accountId);$('mobileStatus').innerHTML=`<span style="color:${connected?'#2d9a56':'#ca8b13'}">●</span><div><b>${connected?'Настройки подготовлены':'Интеграция не подключена'}</b><small>${connected?'Для боевого обмена требуется серверный API личного кабинета.':'Укажите данные клиента и выполните серверную авторизацию.'}</small></div>`;}
function saveObject(){const object=current();if(!object)return;const data=new FormData(form);for(const [key,value] of data)object[key]=String(value).trim();if(!object.number||!object.name||!object.address){toast('Заполните номер, название и адрес');return;}object.mobile.accountId=$('mobileAccountId').value.trim();object.mobile.phone=$('mobilePhone').value.trim();document.querySelectorAll('[data-mobile-setting]').forEach(input=>object.mobile[input.dataset.mobileSetting]=input.checked);saveStore();renderList();renderEditor();toast('Карточка объекта сохранена');}
document.querySelectorAll('.admin-tabs button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.admin-tabs button').forEach(item=>item.classList.remove('active'));document.querySelectorAll('.admin-tab').forEach(tab=>tab.classList.remove('active'));button.classList.add('active');$(`tab-${button.dataset.tab}`).classList.add('active');}));
$('adminSearch').addEventListener('input',()=>{renderList();renderSuggestions();});$('systemFilter').addEventListener('change',renderList);$('categoryFilter').addEventListener('change',renderList);$('saveObjectBtn').addEventListener('click',saveObject);
$('addLoopBtn').addEventListener('click',()=>{current().loops.push({number:String(current().loops.length+1),name:`Шлейф ${current().loops.length+1}`,description:'',zone:'Охранная'});renderLoops();});$('addContactBtn').addEventListener('click',()=>{current().contacts.push({name:'',role:'Ответственное лицо',phone:'',priority:String(current().contacts.length+1)});renderContacts();});
$('newObjectBtn').addEventListener('click',()=>{const object=defaults({id:`obj-${Date.now()}`,number:'',system:'Феникс',name:'Новый объект',address:'',city:'Краснодар',section:'Раздел 1',category:'2',gbr:'',latitude:'',longitude:'',administrator:'',manager:'',service:'Охрана ОС',status:'Действующий',note:''},objects.length);objects.push(object);selectObject(object.id);toast('Создана новая карточка');});
$('duplicateObjectBtn').addEventListener('click',()=>{const source=current(),copy=JSON.parse(JSON.stringify(source));copy.id=`obj-${Date.now()}`;copy.number='';copy.name=`${source.name} — копия`;objects.push(copy);selectObject(copy.id);toast('Карточка продублирована');});
$('deleteObjectBtn').addEventListener('click',()=>{if(objects.length<2||!confirm(`Удалить объект «${current().name}»?`))return;objects=objects.filter(object=>object.id!==selectedId);selectedId=objects[0].id;saveStore();renderList();renderEditor();toast('Объект удалён');});
$('objectPhotoInput').addEventListener('change',event=>{[...event.target.files].slice(0,5).forEach(file=>{if(file.size>1500000){toast('Фото должно быть меньше 1,5 МБ');return;}const reader=new FileReader();reader.onload=()=>{current().photos.push(reader.result);renderPhotos();};reader.readAsDataURL(file);});event.target.value='';});
$('testMobileBtn').addEventListener('click',()=>{current().mobile.accountId=$('mobileAccountId').value.trim();if(!current().mobile.accountId){toast('Введите ID клиента или договора');return;}renderMobile();toast('Поля заполнены. Для подключения нужен серверный API');});
$('adminThemeBtn').addEventListener('click',()=>{document.body.classList.toggle('dark-theme');const dark=document.body.classList.contains('dark-theme');$('adminThemeBtn').textContent=dark?'◐ Светлая тема':'◐ Тёмная тема';localStorage.setItem('neva-admin-theme',dark?'dark':'light');});
if(localStorage.getItem('neva-admin-theme')==='dark'){document.body.classList.add('dark-theme');$('adminThemeBtn').textContent='◐ Светлая тема';}
renderList();renderEditor();
